---倒酒按钮点击回调
function DreamAdventuresPreparationDialog:BtnPourOnClickHandler()
    if self:CheckComplete() then
        local storyId = DreamAdventuresMgr:GetEndingStoryId()
        DreamAdventuresMgr:PlayingPlot({ storyId })
        return
    end

    local pointId = DreamAdventuresMgr:GetActivityPointId()
    local num = GoodsUtils.GetThingNo(pointId)
    if checkInt(num) == 0 then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(pointId)
        GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
        return
    end

    CfUtils.StartCoroutineWithBlocker(function()
        --CfUtils.SetActive(self.BottleSpineRoot, true)
        CfUtils.PlayAnimation(self.BgGroup, "ActivityDreamAdventuresPrepareMain_Pour")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        --CfUtils.SetActive(self.BottleSpineRoot, false)
        GameUtils.Request(Interfaces.DreamAdventuresPourWine, {num = num, activityUuid = DreamAdventuresMgr:GetActivityId()}, Bind(self, self.PourResponseHandler))
    end)
end

