function DreamAdventuresPreparationDialog:DishPopupBtnConfirmOnClickHandler()
    local groupState, groupConf = self:CheckGroupState()
    if groupState == GroupState.NEW then
        GameUtils.Request(Interfaces.DreamAdventBlending, {activityUuid = DreamAdventuresMgr:GetActivityId(), groupId = groupConf.id}, Bind(self, self.BlendingResponseHandler))
    else
        local tips = self:GetGroupTips()
        if tips then
            GameUtils.Toast(tips)
        end
    end
end

---倒酒response处理
function DreamAdventuresPreparationDialog:PourResponseHandler(request, response)
    if checkInt(response.error) ~= 0 then return end
    
    if response.data.rewards then
        GoodsUtils.DrawRewards(response.data.rewards, true)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards}})
    end
    ---扣除消耗
    local pointId = DreamAdventuresMgr:GetActivityPointId()
    local num = GoodsUtils.GetThingNo(pointId)
    local consume = {{goodsId = pointId, num = -num}}
    GoodsUtils.DrawRewards(consume, true)

    DreamAdventuresMgr:SetSelfWinePress(checkInt(response.data.selfPoint))
    DreamAdventuresMgr:SetAllWinePress(checkInt(response.data.allPoint))
    DreamAdventuresMgr:SetModulationMaterialIds(checkTable(response.data.modulationMaterialIds))
    self:RefreshUI()
end

---调配response处理
function DreamAdventuresPreparationDialog:BlendingResponseHandler(request, response)
    if checkInt(response.error) ~= 0 then return end

    CfUtils.StartCoroutineWithBlocker(function()
        CfUtils.PlayAnimation(self.BgGroup, "ActivityDreamAdventuresPrepareMain_DishRootPutIn")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2.3))
        DreamAdventuresMgr:SetNotClaimedDumpingId(checkInt(response.data.dumplingId))
        self:HideMaterialView()
        self:SetViewState(ViewState.INVITATION)
        self:RefreshViewState()
    end)
end

---材料节点点击回调
function DreamAdventuresPreparationDialog:MaterialNodeOnClickHandler(index)
    local materialConf = DreamAdventuresMgr:GetMaterialConf()
    local materialId = materialConf[index].id
    if not DreamAdventuresMgr:CheckMaterialUnlock(materialId) then
        GameUtils.Toast(localize('材料未解锁'))
        return
    end
    
    if self:IsMaterialSelected(index) then
        self:UnselectedMaterial(index)
    else
        if self:CheckSelectedNum() then
            self:SelectedMaterial(index)
            self:ShowGroupTips()
        else
            GameUtils.Toast(localize('最多只能选择3种材料'))
            return
        end
    end
    
    self:RefreshMaterials()
end

---邀请按钮点击回调
function DreamAdventuresPreparationDialog:BtnInviteOnClickHandler()
    local dumplingId = DreamAdventuresMgr:GetNotClaimedDumpingId()
    if dumplingId == 0 then return end

    GameUtils.Request(Interfaces.DreamAdventuresInvite, {activityUuid = DreamAdventuresMgr:GetActivityId()}, Bind(self, self.InviteResponseHandler))
end

---邀请response处理
function DreamAdventuresPreparationDialog:InviteResponseHandler(request, response)
    if checkInt(response.error) ~= 0 then return end
    
    CfUtils.StartCoroutineWithBlocker(function()
        self:HideInviteView()
        self:SetViewState(ViewState.PREPARATION)
        CfUtils.PlayAnimator(self.BtnInviteRoot, "lose")
        CfUtils.PlayAnimation(self.BgGroup, "ActivityDreamAdventuresPrepareMain_DishRootFogOut")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.4))
        local dumplingId = DreamAdventuresMgr:GetNotClaimedDumpingId()
        DreamAdventuresMgr:InviteDumpling(dumplingId)
        DreamAdventuresMgr:SetNotClaimedDumpingId(0)
        self:RefreshViewState()
        local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
        local index = 0
        for i, v in ipairs(dumplingConf) do
            if checkInt(v.id) == dumplingId then
                index = i
                break
            end
        end
        local targetNode = self.ChorusStationRoot:Find(string.format("%d/Node%.2d/SpineRoot", index, index))
        if isNotNull(targetNode) then
            CfUtils.PlayAnimation(targetNode, "ActivityDreamAdventuresPrepareChoralRoleNode_Entry")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))  
        end
        CfUtils.PlayAnimation(self.MainPanel, "ActivityDreamAdventuresPrepareMain_Back")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
        if response.data.rewards then
            GoodsUtils.DrawRewards(response.data.rewards, true)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards}})
        end
    end)
end

---团子点击回调
function DreamAdventuresPreparationDialog:DumplingNodeOnClickHandler(index)
    local node = self.ChorusStationRoot:Find(string.format("%d/Node%.2d/SpineRoot/ImgIcon/Spine", index, index))
    if isNotNull(node) then
        local spine = node.gameObject:GetComponent(typeof(SkeletonGraphic))
        if isNull(spine) then
            spine = node.gameObject:GetComponent(typeof(SkeletonAnimation))
        end
        if isNull(spine) then
            return
        end
        spine.AnimationState:SetAnimation(0, "note_sing_01", false)
        spine.AnimationState:AddAnimation(0, "note_idle_01", true, 0)
        
        -- 播放音效
        local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
        CriWareUtils.PlaySeById(dumplingConf[index].dumplingSound)
        
        -- 记录点击
        if self:GetViewState() == ViewState.CHORUS then
            self:RecordClick(index)
            self:CheckNewChoralScore()
        end
    end
end

--- 解锁曲谱response处理
function DreamAdventuresPreparationDialog:UnlockChoralScoreResponseHandler(request, response)
    if checkInt(response.error) ~= 0 then return end

    CfUtils.DialogOpen(Constants.UITypeIds.ActivityDreamAdventuresCollectRewardPopup, {choralScoreId = checkInt(response.data.choralScoreId)})
    DreamAdventuresMgr:UnlockChoralScore(response.data.choralScoreId)
    if response.data.rewards then
        GoodsUtils.DrawRewards(response.data.rewards, true)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards}})
    end
    
    self:ClearClickQueue()
end
