---刷新页面状态
function DreamAdventuresPreparationDialog:RefreshViewState()
    if self:GetViewState() == ViewState.PREPARATION then
        CfUtils.SetActive(self.ActivityEntryRoot, true)
        CfUtils.SetActive(self.CartoonRoleRoot, true)
        CfUtils.SetActive(self.ChorusStationRoot, true)
        CfUtils.SetActive(self.BlendingRoot, false)
        CfUtils.SetActive(self.DishRoot, false)
        CfUtils.SetActive(self.UIFX_Fog, false)
        CfUtils.SetActive(self.UIFX_smoke, false)
        CfUtils.PlayAnimation(self.ChorusStationRoot, DumplingPositionAnimName.DEFAULT)
        self:RefreshDumplingNode()
        self:RefreshBtn()
    elseif self:GetViewState() == ViewState.BLENDING then
        CfUtils.SetActive(self.ActivityEntryRoot, false)
        CfUtils.SetActive(self.CartoonRoleRoot, false)
        CfUtils.SetActive(self.ChorusStationRoot, false)
        CfUtils.SetActive(self.BlendingRoot, true)
        CfUtils.SetActive(self.DishRoot, true)
        CfUtils.SetActive(self.BtnDish1, true)
        CfUtils.SetActive(self.BtnDish2, true)
        CfUtils.SetActive(self.BtnDish3, true)
        CfUtils.SetActive(self.BtnInvite, false)
        CfUtils.SetActive(self.UIFX_Fog, false)
        CfUtils.SetActive(self.UIFX_smoke, false)
        CfUtils.PlayAnimation(self.BgGroup, "ActivityDreamAdventuresPrepareMain_Default")
        self:RefreshMaterials()
    elseif self:GetViewState() == ViewState.INVITATION then
        CfUtils.SetActive(self.ActivityEntryRoot, false)
        CfUtils.SetActive(self.CartoonRoleRoot, false)
        CfUtils.SetActive(self.ChorusStationRoot, false)
        CfUtils.SetActive(self.BlendingRoot, false)
        CfUtils.SetActive(self.DishRoot, true)
        CfUtils.SetActive(self.BtnDish1, false)
        CfUtils.SetActive(self.BtnDish2, false)
        CfUtils.SetActive(self.BtnDish3, false)
        CfUtils.SetActive(self.BtnInvite, true)
        CfUtils.SetActive(self.UIFX_Fog, true)
        CfUtils.SetActive(self.UIFX_smoke, true)
        self:RefreshInvitationView()
    elseif self:GetViewState() == ViewState.CHORUS then
        CfUtils.SetActive(self.ActivityEntryRoot, false)
        CfUtils.SetActive(self.CartoonRoleRoot, true)
        CfUtils.SetActive(self.ChorusStationRoot, true)
        CfUtils.PlayAnimation(self.ChorusStationRoot, DumplingPositionAnimName.CHORUS)
        self:RefreshChorusView()
    end
end

---刷新邀请界面
function DreamAdventuresPreparationDialog:RefreshInvitationView()
    -- 移除之前的spine
    local childCount = self.BtnInviteSpine.childCount
    if childCount > 0 then
        for i = 0, childCount - 1 do
            GameObject.Destroy(self.BtnInviteSpine:GetChild(i).gameObject)
        end
    end 
    
    local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
    local dumplingId = DreamAdventuresMgr:GetNotClaimedDumpingId()
    if dumplingId == 0 then return end
    
    local index = 0
    for i, v in ipairs(dumplingConf) do
        if checkInt(v.id) == dumplingId then
            index = i
            break
        end
    end
    -- 创建spine
    local targetNode = self.ChorusStationRoot:Find(string.format("%d", index))
    local spine = nil
    if isNotNull(targetNode) then
        spine = GameObject.Instantiate(targetNode.gameObject, self.BtnInviteSpine)
        spine.transform.localPosition = Vector3.zero
        spine.transform.localScale = Vector3.one
        CfUtils.SetActive(spine, true)
    end
    
    local node = spine.transform:GetChild(0)
    if isNotNull(node) then
        SetButtonAction(self.BtnInvite,function() 
            self:ShowInviteView(dumplingConf[index])
        end)
    end
end

