---刷新按钮
function DreamAdventuresPreparationDialog:RefreshBtn()
    -- 全服奖励
    local allPercent = DreamAdventuresMgr:GetAllRewardsPercentage()
    CfUtils.FillText(self.AllScheduleTextNum, string.format('%s%%', math.floor(allPercent * 1000) / 10))

    -- 个人奖励
    local rewardsList = DreamAdventuresMgr:GetPersonalRewardsList()
    local point = DreamAdventuresMgr:GetSelfWinePress()
    local targetPoint = checkInt(rewardsList[#rewardsList].point)
    CfUtils.FillText(self.PlayerScheduleTextNum, string.format('%d<color=#FFFFFF>/%d</color>', math.min(point, targetPoint), targetPoint))


    -- 祭酒
    if self:CheckComplete() then
        self:CheckEnding()
        CfUtils.SetActive(self.UIFX_Pour, false)
        CfUtils.SetActive(self.PourImgIcon, false)
        CfUtils.SetActive(self.PourTextTitlePlayer, false)
        CfUtils.SetActive(self.ImgBgTitlePlayer, false)
        CfUtils.FillText(self.Text, localize('回看'))
    else
        local pointId = DreamAdventuresMgr:GetActivityPointId()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(pointId)
        CfUtils.FillImage(self.PourImgIcon, goodsVo.photoPath)
        local num = GoodsUtils.GetThingNo(pointId)
        CfUtils.FillText(self.PourTextTitlePlayer, num)
        CfUtils.SetActive(self.ImgBgTitlePlayer, true)
        CfUtils.SetActive(self.UIFX_Pour, num > 0)
    end
    
    -- 社群
    local url = DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.ASSOCIATION_URL)
    CfUtils.SetActive(self.BtnAssociation, tostring(url) ~= "")
    
    -- 合唱谱
    local dumplingIds = DreamAdventuresMgr:GetDumplingIds()
    local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
    CfUtils.FillText(self.BtnCollectTxtNum, string.format("%d/%d", #dumplingIds, #dumplingConf))

    if self:IsCollectionFinished() then
        CfUtils.FillText(self.BtnBlendingTxtTitle, localize('合唱模式'))
        CfUtils.SetActive(self.BtnBlendingRedPoint, false)
    else
        CfUtils.FillText(self.BtnBlendingTxtTitle, localize('风味调制'))
        CfUtils.SetActive(self.BtnBlendingRedPoint, self:ExistInviteDumpling())
        
    end
end

---刷新团子节点
function DreamAdventuresPreparationDialog:RefreshDumplingNode()
    local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
    for i, v in ipairs(dumplingConf) do
        local child = self.ChorusStationRoot:Find(string.format("%d", i))
        local node = self.ChorusStationRoot:Find(string.format("%d/Node%.2d", i, i))
        if isNotNull(child) and isNotNull(node) then
            SetButtonAction(node, Bind(self, self.DumplingNodeOnClickHandler, i))
            if DreamAdventuresMgr:CheckDumplingUnlock(v.id) then
                CfUtils.SetActive(child, true)   
            else
                CfUtils.SetActive(child, false)
            end
        end
    end
end

---刷新红点
function DreamAdventuresPreparationDialog:RefreshRedPoint()
    CfUtils.SetActive(self.BtnAllScheduleRedPoint, DreamAdventuresMgr:GetPreparationAllRewardsRedPointState())
    CfUtils.SetActive(self.BtnPlayerScheduleRedPoint, DreamAdventuresMgr:GetPreparationPersonalRedPointState())
end

---检查准备阶段是否完成
function DreamAdventuresPreparationDialog:CheckComplete()
    local selfPoint = DreamAdventuresMgr:GetSelfWinePress()
    local rewardsList = DreamAdventuresMgr:GetPersonalRewardsList()
    if selfPoint < checkInt(rewardsList[#rewardsList].point) then
        return false
    end
    
    local allPoint = DreamAdventuresMgr:GetAllWinePress()
    local allRewardsList = DreamAdventuresMgr:GetAllRewardsList()
    if allPoint < checkInt(allRewardsList[#allRewardsList].point) then
        return false
    end
    return true
end

---检查终章
function DreamAdventuresPreparationDialog:CheckEnding()
    local activityId = DreamAdventuresMgr:GetActivityId()
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = playerComp.playerDojo.playerId
    local key = string.format('DreamAdventuresEnding%s%s', activityId, playerId)
    local value = CfUtils.GetLocalData(key, 0)
    if checkInt(value) > 0 then return end

    CfUtils.WriteLocalData(key, 1)
    local storyId = DreamAdventuresMgr:GetEndingStoryId()
    DreamAdventuresMgr:PlayingPlot({ storyId })
end

---显示材料界面
function DreamAdventuresPreparationDialog:ShowMaterialView()
    CfUtils.StartCoroutineWithBlocker(function() 
        CfUtils.PlayAnimation(self.MainPanel, "ActivityDreamAdventuresPrepareMain_Out")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
        
        self:ClearSelectedMaterials()
        self:SetViewState(ViewState.BLENDING)
        self:RefreshViewState()

        CfUtils.SetTopCommonCb(function()
            CfUtils.StartCoroutineWithBlocker(function()
                self:HideMaterialView()
                self:ResetOrderTracker()
                CfUtils.PlayAnimation(self.MainPanel, "ActivityDreamAdventuresPrepareMain_Back")
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
                self:SetViewState(ViewState.PREPARATION)
                self:RefreshViewState()
            end)
        end)
    end)
end

---显示合唱界面
function DreamAdventuresPreparationDialog:ShowChorusView()
    self:SetViewState(ViewState.CHORUS)
    self:RefreshViewState()
    self:ClearClickQueue()
    -- 停止bgm
    DreamAdventuresMgr:StopBGM()
    
    -- 转换位置动画
    CfUtils.StartCoroutineWithBlocker(function()
        CfUtils.PlayAnimation(self.ChorusStationRoot, DumplingPositionAnimName.DEFAULT)
        CfUtils.PlayAnimation(self.ChorusStationRoot, DumplingPositionAnimName.CHANGE_TO_CHORUS)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.55))
    end)

    CfUtils.SetTopCommonCb(function()
        CfUtils.StartCoroutineWithBlocker(function()
            CfUtils.PlayAnimation(self.ChorusStationRoot, DumplingPositionAnimName.BACK)
            CfUtils.PlayAnimation(self.MainPanel, "ActivityDreamAdventuresPrepareMain_Back")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
            self:SetViewState(ViewState.PREPARATION)
            self:RefreshViewState()
            DreamAdventuresMgr:PlayBGM()
            CfUtils.ResetNavigatorCustomBackAction()
            self:ResetOrderTracker()
        end)
    end)
end

