---刷新材料列表
function DreamAdventuresPreparationDialog:RefreshMaterialList()
    local materialConf = DreamAdventuresMgr:GetMaterialConf()
    local count = self.DishPopupRoot.childCount
    if count < #materialConf then
        for i = count, #materialConf - 1 do
            GameObject.Instantiate(self.BtnDish.gameObject, self.DishPopupRoot)
        end
    end
    
    for i = 1, #materialConf do
        local node = self.DishPopupRoot:GetChild(i - 1)
        local scr = CfUtils.GetLuaScr(node, DreamAdventuresConstants.ScrPath.DreamAdventuresPreparationMaterialNode)
        if isNotNull(scr) then
            scr:RefreshNode(materialConf[i], i, Bind(self, self.MaterialNodeOnClickHandler))
            scr:SetSelected(self:IsMaterialSelected(i))
        end
    end
    
    local textNum = localize("已选择:<color=#FF9A46><size=36>_num1_</size></color><color=#9C9A99><size=36>/_num2_</size></color>", {_num1_ = #self._selectedMaterials, _num2_ = MATERIAL_SELECTED_LIMIT})
    CfUtils.FillText(self.DishPopupTextNum, textNum)

    local groupState = self:CheckGroupState()
    local font = Constants.ButtonFontStyle.B18
    if groupState == GroupState.NEW then
        font = Constants.ButtonFontStyle.B6
    end
    CfUtils.SetButtonStyle(self.DishPopupBtnConfirm, font, localize("投入酒壶"))
    
end

---刷新选中的材料
function DreamAdventuresPreparationDialog:RefreshSelectedMaterials()
    local materialConf = DreamAdventuresMgr:GetMaterialConf()
    local selectedList = self:GetSelectedMaterials()
    for i = 1, 3 do
        local node = self['BtnDish' .. i]
        if isNotNull(node) then
            local index = selectedList[i]
            local imgIcon = node:Find('ImgIcon')
            if index then
                CfUtils.SetActive(imgIcon, true)
                local conf = materialConf[index]
                CfUtils.FillImage(imgIcon, conf.icon)
            else
                CfUtils.SetActive(imgIcon, false)
            end
        end
    end
end

---检查材料是否选中
function DreamAdventuresPreparationDialog:IsMaterialSelected(index)
    for _, v in ipairs(self._selectedMaterials) do
        if v == index then
            return true
        end
    end
    return false
end

---检查材料选中数量
function DreamAdventuresPreparationDialog:CheckSelectedNum()
    local selectedCount = #self._selectedMaterials
    if selectedCount >= MATERIAL_SELECTED_LIMIT then
        return false
    end
    
    return true
end

---选中材料
function DreamAdventuresPreparationDialog:SelectedMaterial(index)
    table.insert(self._selectedMaterials, index)
