---检查组合状态
---@return number, table @组合状态, 组合配置
function DreamAdventuresPreparationDialog:CheckGroupState()
    local groupState = GroupState.NONE
    if #self:GetSelectedMaterials() ~= MATERIAL_SELECTED_LIMIT then
        return groupState
    end
    
    local materialConf = DreamAdventuresMgr:GetMaterialConf()
    local selectedList = self:GetSelectedMaterials()
    local selectedIds = {}
    for _, v in ipairs(selectedList) do
        table.insert(selectedIds, materialConf[v].id)
    end
    
    
    local dumplingMatchList = DreamAdventuresMgr:GetMaterialMatchConf()
    local groupConf = nil
    for _, v in ipairs(dumplingMatchList) do
        if self:ArrayEqual(v.materialId, selectedIds) then
            groupConf = v
            if v.dumplingId == 0 then
                groupState = GroupState.FAIL
            else
                if DreamAdventuresMgr:CheckDumplingUnlock(v.dumplingId) then
                    groupState = GroupState.OLD
                else
                    groupState = GroupState.NEW
                end
            end
            break
        end
    end
    
    return groupState, groupConf
end

---检查组合是否相同
function DreamAdventuresPreparationDialog:ArrayEqual(a, b)
    if #a ~= #b then return false end
    for i = 1, #a do
        local equal = false
        for j = 1, #b do
            if checkInt(a[i]) == checkInt(b[j]) then
                equal = true
                break
            end
        end
        if not equal then return false end
    end
    return true
end

