---团子是否收集完成
function DreamAdventuresPreparationDialog:IsCollectionFinished()
    local dumplingList = DreamAdventuresMgr:GetDumplingIds()
    local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
    if #dumplingList == #dumplingConf then
        return true
    end
    return false
