---记录点击
function DreamAdventuresPreparationDialog:RecordClick(index)
    if #self._clickQueue >= ClickQueueLimit then
        table.remove(self._clickQueue, 1)
    end
    table.insert(self._clickQueue, index)
end

---判断是否新的合唱谱
function DreamAdventuresPreparationDialog:CheckNewChoralScore()
    local scoreConf = DreamAdventuresMgr:GetChoralScoreConf()
    local clickQueue = self._clickQueue
    local clickStr = nil
    for _, v in ipairs(clickQueue) do
        if clickStr then
            clickStr = clickStr .. ';' .. v
        else
            clickStr = v
        end
    end
    print(clickStr)
    
    for _, v in ipairs(scoreConf) do
        if not DreamAdventuresMgr:CheckChoralScoreUnlock(v.id) then
            local pos = string.find(clickStr, v.dumplingGroup)
            if pos then
                local list = string.split(v.dumplingGroup, ';')
                for i = 1, #list do
                    list[i] = checkInt(list[i])
                end
                local dumplingIds = table.serialize(list)
                GameUtils.Request(Interfaces.DreamAdventuresChorus, {activityUuid = DreamAdventuresMgr:GetActivityId(), dumplingIds = dumplingIds}, Bind(self, self.UnlockChoralScoreResponseHandler))
                return 
            end
        end
    end
end

---清空点击队列
function DreamAdventuresPreparationDialog:ClearClickQueue()
    self._clickQueue = {}
end

---是否存在可邀请的团子
function DreamAdventuresPreparationDialog:ExistInviteDumpling()
    local dumplingMatchList = DreamAdventuresMgr:GetMaterialMatchConf()
    for _, v in ipairs(dumplingMatchList) do
        if not DreamAdventuresMgr:CheckDumplingUnlock(v.dumplingId) then
            local canInvite = true
            for _, materialId in ipairs(v.materialId) do
                if not DreamAdventuresMgr:CheckMaterialUnlock(materialId) then
                    canInvite = false
                    break
                end
            end
            if canInvite then
                return true
            end
        end
    end
    return false
end
