---获取选中的材料
function DreamAdventuresPreparationDialog:GetSelectedMaterials()
    return self._selectedMaterials
end

---获取组合提示
function DreamAdventuresPreparationDialog:GetGroupTips()
    local groupState, groupConf = self:CheckGroupState()
    if groupState == GroupState.NONE then
        return
    elseif groupState == GroupState.NEW then
        return groupConf.groupTitleNew
    elseif groupState == GroupState.OLD then
        return groupConf.groupTitleOld
    elseif groupState == GroupState.FAIL then
        return groupConf.groupTitleFail
    end
end

